  `questions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '题目列表（JSON格式）',
  `user_answers` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '用户答案（JSON格式）',
  `correct_answers` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '正确答案（JSON格式）',
  `results` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '详细批改结果（JSON格式，包含每道题的反馈）',
  `score` float NULL DEFAULT NULL COMMENT '得分',
  `accuracy` float NULL DEFAULT NULL COMMENT '正确率（0-100）',
