  `is_completed` int NULL DEFAULT NULL COMMENT '是否完成（1=是，0=否）',
  `started_at` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `section_id` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ix_quiz_records_id`(`id` ASC) USING BTREE,
  INDEX `ix_quiz_records_subsection_id`(`subsection_id` ASC) USING BTREE,
  INDEX `ix_quiz_records_quiz_type`(`quiz_type` ASC) USING BTREE,
  INDEX `ix_quiz_records_user_id`(`user_id` ASC) USING BTREE,
  INDEX `ix_quiz_records_practice_mode`(`practice_mode` ASC) USING BTREE,
  INDEX `ix_quiz_records_chapter_id`(`chapter_id` ASC) USING BTREE,
  CONSTRAINT `quiz_records_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `quiz_records_ibfk_2` FOREIGN KEY (`chapter_id`) REFERENCES `chapters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `quiz_records_ibfk_3` FOREIGN KEY (`subsection_id`) REFERENCES `subsections` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 115 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

