INSERT INTO `quiz_records` VALUES (93, 2, 36, NULL, 'random', 'mixed', '初级', 4, '[{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一名新员工，第一天上班时需要向团队成员做自我介绍。写一篇短文介绍你自己，包括你的职位、所在部门以及你的工作职责。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下词汇：colleague, introduce, position, department, responsible\", \"必须体现一般现在时的用法\"], \"word_count\": \"80-120词\"}, {\"quiz_type\": \"translation\", \"question_text\": \"她负责市场部门的声誉管理。\", \"correct_answer\": \"\", \"explanation\": \"\"}, {\"quiz_type\": \"writing\", \"question_text\": \"假设你是一名公司员工，你需要向新同事介绍你自己和你的工作。请写一段简短的自我介绍，描述你的职位、部门以及你负责的工作。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下词汇中的至少5个：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须使用一般现在时来描述你当前的工作情况和职责\"], \"word_count\": \"80-120词\"}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下句子翻译成英文：他在部门负责项目，并期待与同事交换名片。\"}]', '[\"ppppp\", \"iiiiiiiiii\", \"iiiiiiiiiiiiii\", \"iiiiiiiiiiiiiii\"]', '[null, \"\", null, null]', '[{\"question_index\": 0, \"user_answer\": \"ppppp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"iiiiiiiiii\", \"correct_answer\": \"\", \"is_correct\": false, \"score\": 0.0, \"feedback\": \"无法评估翻译质量，因为缺少英文原文和参考答案。学生的答案\'iiiiiiiiii\'看起来不是有效的翻译内容。\\n\\n💡 改进建议：\\n• 请提供完整的英文原文和参考答案以便进行准确评估\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"iiiiiiiiiiiiii\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"iiiiiiiiiiiiiii\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"答案无效。提交的内容是一串\'i\'字符，不是有效的翻译。\\n\\n💡 改进建议：\\n• 请认真阅读原文并提供有意义的翻译\\n• 确保翻译内容与原文意思相符\", \"explanation\": \"\"}]', 10, 0, 25, NULL, 1, NULL, '2026-01-30 14:13:43', '2026-01-30 14:13:00', NULL);
INSERT INTO `quiz_records` VALUES (94, 2, 36, NULL, 'random', 'mixed', '中级', 5, '[{\"quiz_type\": \"translation\", \"question_text\": \"我的同事李先生负责销售部门，他经常向新客户介绍我们的公司声誉和专业知识，并期待与他们交换名片。\"}, {\"quiz_type\": \"writing\", \"question_text\": \"Imagine you are a new employee in a company. Write a short self-introduction to your colleagues. In your writing, you should introduce yourself and your position, describe your department and what you are responsible for, and express what you look forward to in your new job.\", \"requirements\": [\"Word count: 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use the simple present tense correctly\"], \"word_count\": \"80-120\"}, {\"quiz_type\": \"writing\", \"question_text\": \"假设你是一名在公司工作的员工。请写一段短文，描述你的工作职责以及你如何与同事互动。内容包括你的职位、所在部门、你负责的工作，以及你与新同事交流的方式。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下词汇：colleague, introduce, position, department, responsible, in charge of, look forward to\", \"使用一般现在时描述你的日常工作职责和与同事的互动\"], \"word_count\": \"80-120词\"}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文翻译成英文：我的同事李明负责销售部门，他期待与新客户交换名片并介绍我们公司的专业知识和声誉。\"}, {\"quiz_type\": \"translation\", \"question_text\": \"我的同事李明负责市场部门，他期待与新客户交换名片并介绍我们的专业知识和声誉。\", \"correct_answer\": \"\", \"explanation\": \"\"}]', '[\"wwwwwwwww\", \"wwwwwwwwwww\", \"wwwwwwwww\", \"wwwwwww\", \"ppp\"]', '[null, null, null, null, \"\"]', '[{\"question_index\": 0, \"user_answer\": \"wwwwwwwww\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"学生答案\'wwwwwwwww\'不是有效的翻译，无法理解其含义。请提供有意义的翻译内容。\\n\\n💡 改进建议：\\n• 请确保翻译内容表达清晰、有意义\\n• 建议重新理解原文并进行翻译\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"wwwwwwwwwww\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"wwwwwwwww\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"wwwwwww\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"学生的回答\'wwwwwww\'不是一个有效的翻译，没有传达任何意义。\\n\\n💡 改进建议：\\n• 请提供实际的翻译内容，确保翻译准确传达原文意思\", \"explanation\": \"\"}, {\"question_index\": 4, \"user_answer\": \"ppp\", \"correct_answer\": \"\", \"is_correct\": false, \"score\": 0.0, \"feedback\": \"学生答案仅为\'ppp\'，未能完成翻译任务。无法评估翻译质量，因为缺少有效的翻译内容。\\n\\n💡 改进建议：\\n• 请提供完整的翻译内容\\n• 确保理解原文意思后再进行翻译\", \"explanation\": \"\"}]', 8, 0, 24, NULL, 1, NULL, '2026-01-30 14:15:42', '2026-01-30 14:14:41', NULL);
INSERT INTO `quiz_records` VALUES (95, 2, 36, NULL, 'random', 'mixed', '高级', 3, '[{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：作为市场部的负责人，我经常向新同事介绍我们的职位和部门职责，我们负责维护公司的声誉并展示我们的专业知识，我期待在会议中与合作伙伴交换名片。\"}, {\"quiz_type\": \"reading\", \"passage\": \"John works as a senior manager in the Marketing department. He is responsible for international projects. John has a good reputation among his colleagues because of his expertise in digital marketing. Every Monday, he introduces new marketing strategies to his team. Sarah is in charge of the social media team. She and John exchange cards at business meetings. They look forward to expanding their department\'s influence in the market.\", \"questions\": [{\"question_text\": \"What does the underlined word \\\"reputation\\\" mean in the passage?\", \"options\": {\"A\": \"The way someone is looked at or thought about by others\", \"B\": \"The amount of money someone earns\", \"C\": \"The physical appearance of a person\", \"D\": \"The ability to complete difficult tasks\"}}, {\"question_text\": \"What does the underlined word \\\"expertise\\\" refer to in the context?\", \"options\": {\"A\": \"Specialized knowledge or skills in a particular field\", \"B\": \"The experience of working in many different companies\", \"C\": \"The ability to communicate effectively\", \"D\": \"The willingness to help others\"}}, {\"question_text\": \"Which department is John in charge of?\", \"options\": {\"A\": \"Finance department\", \"B\": \"Human Resources department\", \"C\": \"Marketing department\", \"D\": \"Social Media department\"}}, {\"question_text\": \"What do John and Sarah do at business meetings?\", \"options\": {\"A\": \"They discuss marketing strategies\", \"B\": \"They introduce new colleagues\", \"C\": \"They exchange cards\", \"D\": \"They plan department expansions\"}}, {\"question_text\": \"Which of the following sentences correctly uses the simple present tense?\", \"options\": {\"A\": \"John is introducing new marketing strategies now.\", \"B\": \"John introduces new marketing strategies every Monday.\", \"C\": \"John will introduce new marketing strategies next week.\", \"D\": \"John introduced new marketing strategies last Monday.\"}}]}, {\"quiz_type\": \"writing\", \"question_text\": \"Write a professional self-introduction for a new employee orientation meeting at an international company. In your introduction, include information about your role, responsibilities, and how you plan to collaborate with colleagues. Explain why your position is important for the department\'s reputation and success.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use simple present tense to describe your job responsibilities and professional identity\"], \"word_count\": \"80-120 words\"}]', NULL, NULL, NULL, 0, 0, 0, NULL, 0, NULL, NULL, '2026-01-30 14:16:38', NULL);
INSERT INTO `quiz_records` VALUES (96, 2, 36, NULL, 'random', 'mixed', '中级', 5, '[{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：李经理是我们的同事，他负责销售部门，以其专业知识享有良好声誉，并期待在会议上与客户交换名片。\"}, {\"quiz_type\": \"writing\", \"question_text\": \"假设你是一家公司的新员工，你需要向团队成员介绍自己和你的一位同事。请写一篇短文介绍你们各自的职位、部门、工作职责以及你对未来合作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个给定词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须正确使用一般现在时，包括第三人称单数的变化\"], \"word_count\": \"80-120词\"}, {\"quiz_type\": \"reading\", \"question_text\": \"What does the word \'responsible\' mean in the passage?\", \"options\": {\"A\": \"擅长的\", \"B\": \"负责的\", \"C\": \"专业的\", \"D\": \"有经验的\"}, \"passage\": \"Tom is my new colleague at the office. He works in the Marketing department. I introduce him to everyone on his first day. Tom is responsible for social media campaigns. He is in charge of the company\'s online presence. We exchange cards during the morning meeting. Tom has excellent expertise in digital marketing. He builds a good reputation quickly in the company. Everyone looks forward to working with him on future projects.\"}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事经常向新员工介绍他的职位和部门，他负责维护公司的声誉并展示他的专业知识，他期待与客户交换名片。\"}, {\"quiz_type\": \"writing\", \"question_text\": \"Write a self-introduction email to your new colleagues on your first day at a new company.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the given vocabulary words (colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards)\", \"Use the simple present tense correctly to describe your job responsibilities and expectations\", \"Include information about your position, department, and what you are responsible for\", \"Mention how you look forward to working with your new colleagues\"], \"word_count\": \"80-120 words\"}]', '[\"oo\", \"pp\", \"D\", \"ppp\", \"ppp\"]', '[null, null, null, null, null]', '[{\"question_index\": 0, \"user_answer\": \"oo\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"学生的答案\'oo\'不是一个有效的翻译。请提供完整的翻译内容。\\n\\n💡 改进建议：\\n• 请仔细阅读原文并提供完整的翻译\\n• 确保翻译传达了原文的核心意思\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"pp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"D\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"无法判断答案正确性，因为标准答案为None。\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"ppp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"未提供有效的翻译内容。请根据英文原文进行翻译。\\n\\n💡 改进建议：\\n• 需要根据原文内容进行翻译\\n• 避免使用无意义的字符作为答案\", \"explanation\": \"\"}, {\"question_index\": 4, \"user_answer\": \"ppp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}]', 8, 0, 89, NULL, 1, NULL, '2026-01-30 14:28:44', '2026-01-30 14:26:12', NULL);
INSERT INTO `quiz_records` VALUES (97, 2, 36, NULL, 'random', 'mixed', '中级', 5, '[{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文翻译成英文：\", \"passage\": \"我的同事李明负责市场部，他经常向新员工介绍自己的职位和部门，并期待与客户交换名片以建立良好的声誉。\"}, {\"quiz_type\": \"reading\", \"passage\": \"Tom works in the Marketing Department. He is responsible for the company\'s online campaigns. His colleague, Lisa, introduces him to new team members. Lisa has a good reputation in the company because of her expertise in social media. Tom is in charge of the email marketing team. They look forward to launching the new product next month. At business meetings, they always exchange cards with potential clients.\", \"question_text\": \"According to the passage, what is Tom responsible for?\", \"options\": {\"A\": \"Introducing new team members\", \"B\": \"The company\'s online campaigns\", \"C\": \"Exchanging cards with clients\", \"D\": \"Managing Lisa\'s work\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：作为市场部的负责人，我经常向新同事介绍我的职位和专业知识，并与他们交换名片，我期待与他们合作以维护我们部门的声誉。\", \"correct_answer\": \"\", \"explanation\": \"\"}, {\"quiz_type\": \"reading\", \"question_text\": \"What does \'responsible\' mean in the context of the passage?\", \"options\": {\"A\": \"Answerable for duties\", \"B\": \"Able to respond quickly\", \"C\": \"Having a lot of work\", \"D\": \"Being important\"}, \"passage\": \"John works in a large company. He has many colleagues in his department. His position is Marketing Manager. He is responsible for promoting products. John has a good reputation in the company because of his expertise. He is in charge of the marketing team. Every day, John introduces new ideas to his team. They look forward to the weekly meetings. When they meet clients, they always exchange cards. John enjoys his job and works hard every day.\"}, {\"quiz_type\": \"writing\", \"question_text\": \"Write a short paragraph introducing a new colleague to your team members. Include information about his/her position, department, responsibilities, and professional background.\", \"requirements\": [\"Write between 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use the simple present tense correctly to describe the colleague\'s responsibilities and role\"], \"word_count\": \"80-120 words\"}]', '[\"lll\", \"C\", \"ooo\", \"D\", \"00\"]', '[null, null, \"\", null, null]', '[{\"question_index\": 0, \"user_answer\": \"lll\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.1, \"feedback\": \"无法评估翻译质量，因为未提供英文原文，且学生答案\'lll\'不像是有效的翻译。\\n\\n💡 改进建议：\\n• 请确保理解题目要求并提供完整的翻译\\n• 建议检查是否提交了正确的答案\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"C\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"标准答案为None，表示没有正确选项，而学生选择了C，因此答案不正确。\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"ooo\", \"correct_answer\": \"\", \"is_correct\": false, \"score\": 0, \"feedback\": \"无法评估翻译质量，因为缺少必要的评估信息：英文原文、参考答案和学生完整翻译。\\n\\n💡 改进建议：\\n• 请提供完整的英文原文、参考答案和学生翻译答案\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"D\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"答案不正确。标准答案是None，而学生选择了D。\", \"explanation\": \"\"}, {\"question_index\": 4, \"user_answer\": \"00\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}]', 6, 0, 79, NULL, 1, NULL, '2026-01-30 15:27:10', '2026-01-30 15:23:06', 66);
INSERT INTO `quiz_records` VALUES (98, 2, 36, NULL, 'random', 'mixed', '中级', 5, '[{\"quiz_type\": \"writing\", \"question_text\": \"假设你刚加入一家新公司，需要在部门会议上做自我介绍。请写一段80-120词的短文，介绍你的职位、职责以及你对新工作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下至少5个词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须使用一般现在时描述你的职责和日常工作\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事李明经常向新员工介绍他的职位和部门，他负责维护公司的声誉，并期待与客户交换名片以展示他的专业知识。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事在公司负责这个部门，他经常介绍自己的职位，并且期待与客户交换名片以建立良好的声誉。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：\", \"passage\": \"我的同事李明负责市场部，他向新员工介绍自己的职位并期待与他们交换名片。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我负责向新同事介绍我们的部门，并期待与他们交换名片，分享专业知识。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}]', '[\"dsa\", \"asd\", \"asd\", \"asd\", \"dasd\"]', '[null, null, null, null, null]', '[{\"question_index\": 0, \"user_answer\": \"dsa\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"asd\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"答案\'asd\'不是一个有效的翻译。请提供完整的英文原文和有意义的翻译内容。\\n\\n💡 改进建议：\\n• 请认真阅读原文并理解其含义\\n• 确保翻译内容传达原文的核心意思\\n• 避免使用无意义的字符作为答案\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"asd\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.1, \"feedback\": \"翻译未表达出任何有意义的内容。请确保理解原文并提供准确的翻译。\\n\\n💡 改进建议：\\n• 需要认真理解原文\\n• 提供有意义的翻译内容\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"asd\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.1, \"feedback\": \"学生没有提供有效的翻译。答案\'asd\'没有表达任何有意义的内容，无法判断翻译能力。\\n\\n💡 改进建议：\\n• 请认真理解原文并提供完整的翻译\\n• 避免使用无意义的字符作为答案\", \"explanation\": \"\"}, {\"question_index\": 4, \"user_answer\": \"dasd\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.1, \"feedback\": \"答案\'dasd\'看起来像是随机输入的字符，没有表达出任何有意义的翻译内容。请确保理解原文并提供准确的翻译。\\n\\n💡 改进建议：\\n• 需要理解原文意思\\n• 需要提供有意义的翻译内容\", \"explanation\": \"\"}]', 10, 0, 103, NULL, 1, NULL, '2026-01-30 16:06:22', '2026-01-30 15:53:27', 66);
INSERT INTO `quiz_records` VALUES (99, 2, 36, NULL, 'random', 'mixed', '中级', 5, '[{\"quiz_type\": \"reading\", \"question_text\": \"According to the passage, what is the department known for?\", \"options\": {\"A\": \"Having many colleagues\", \"B\": \"Good reputation for creativity\", \"C\": \"Digital marketing expertise\", \"D\": \"Exchanging cards\"}, \"passage\": \"In our company, I work with many colleagues in the marketing department. My manager introduces new team members to everyone. She holds a senior position and is responsible for important projects. Our department has a good reputation for creativity. John, who is in charge of digital marketing, has great expertise in social media. We always exchange cards during business meetings. I look forward to working with this talented team every day.\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为中级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事负责介绍新员工的职位和部门，他期待与每个人交换名片。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"writing\", \"question_text\": \"Write a short paragraph to introduce a new colleague to your team members. Include information about their position, department, and what they are responsible for. Also mention how your team will benefit from their expertise and reputation.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use simple present tense correctly, including third person singular forms (e.g., \'He works\' not \'He work\')\"], \"word_count\": \"80-120 words\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"writing\", \"question_text\": \"假设你是一家公司的新员工，你需要在部门会议上做一个简短的自我介绍。请写一篇80-120词的短文，介绍你的职位、工作职责以及你对新工作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个下列词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须使用一般现在时描述你的工作职责和习惯\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我们的新同事经常向客户介绍他的职位和他负责的部门。他在公司有很好的声誉，因为他在专业领域有丰富的知识。他期待与合作伙伴交换名片。\", \"correct_answer\": \"\", \"explanation\": \"\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}]', '[\"B\", \"ppp\", \"pp\", \"pp\", \"p\"]', '[null, null, null, null, \"\"]', '[{\"question_index\": 0, \"user_answer\": \"B\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"标准答案为None，学生答案为B，两者不匹配。\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"ppp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"无法评估翻译质量，因为缺少英文原文和有效的翻译内容。\\n\\n💡 改进建议：\\n• 请提供完整的英文原文和翻译内容\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"pp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"pp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 4, \"user_answer\": \"p\", \"correct_answer\": \"\", \"is_correct\": false, \"score\": 0.0, \"feedback\": \"无法评估翻译质量，因为缺少英文原文和参考答案，且学生答案仅为单个字母\'p\'，不构成有效翻译。\\n\\n💡 改进建议：\\n• 请提供完整的英文原文和参考答案\\n• 学生需要提交完整的翻译内容\", \"explanation\": \"\"}]', 8, 0, 53, NULL, 1, NULL, '2026-01-30 16:31:36', '2026-01-30 16:30:25', 66);
INSERT INTO `quiz_records` VALUES (100, 2, 36, NULL, 'random', 'mixed', '中级', 5, '[{\"quiz_type\": \"writing\", \"question_text\": \"Write a short paragraph introducing yourself or a colleague at work. Describe the position, department, and responsibilities. Also mention your/their professional reputation and expertise.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the given vocabulary words\", \"Apply the simple present tense correctly\", \"Include at least two compound sentences\"], \"word_count\": \"80-120 words\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"writing\", \"question_text\": \"假设你在一家公司工作，你需要向新来的同事介绍自己的工作职责和期望。请写一段自我介绍，包括你的职位、所在部门、工作职责以及你对未来合作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个给定词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须体现核心语法：一般现在时（特别是第三人称单数的使用）\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"writing\", \"question_text\": \"假设你是一家公司的新员工，请写一篇短文介绍你的工作情况。在短文中，你需要描述你的职位、所在部门、你的工作职责以及你与同事的合作关系。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个以下词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须正确使用一般现在时\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"reading\", \"question_text\": \"What does the word \'reputation\' mean in the passage?\", \"options\": {\"A\": \"The ability to do something well\", \"B\": \"The opinions that people have about someone or something\", \"C\": \"The department where someone works\", \"D\": \"The position that someone holds in a company\"}, \"passage\": \"John is my colleague at the marketing department. He introduces new products to clients. His position is Senior Manager. John is responsible for the Asia region. He has a good reputation for his expertise in digital marketing. He is in charge of a team of ten people. We look forward to working together on the new project. We often exchange cards at business meetings.\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为中级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事经常向新员工介绍我们的职位、部门以及我们负责的内容，我们期待与客户交换名片并展示公司的声誉和专业知识。\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}]', '[\"qqq\", \"qqq\", \"qqq\", \"B\", \"qqq\"]', '[null, null, null, null, null]', '[{\"question_index\": 0, \"user_answer\": \"qqq\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"qqq\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"qqq\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"B\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"标准答案为None，表示没有正确答案，学生选择B不正确。\", \"explanation\": \"\"}, {\"question_index\": 4, \"user_answer\": \"qqq\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"学生答案\'qqq\'不是一个有效的翻译，无法评估翻译质量。\\n\\n💡 改进建议：\\n• 请提供完整的翻译内容\\n• 确保翻译准确传达原文意思\", \"explanation\": \"\"}]', 12, 0, 12, NULL, 1, NULL, '2026-01-30 16:52:46', '2026-01-30 16:52:20', 66);
