INSERT INTO `quiz_records` VALUES (104, 10, 36, NULL, 'random', 'mixed', '初级', 4, '[{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事介绍他的职位和部门。\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为初级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"writing\", \"question_text\": \"Write a short self-introduction for a new job. Imagine you are the new employee at a company and you need to introduce yourself to your colleagues.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use simple present tense to describe your job responsibilities and daily activities\"], \"word_count\": \"80-120 words\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为初级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"reading\", \"question_text\": \"What is Mr. Smith\'s position in the company?\", \"options\": {\"A\": \"Marketing Department Manager\", \"B\": \"Senior Marketing Manager\", \"C\": \"Digital Marketing Expert\", \"D\": \"Advertising Campaign Manager\"}, \"passage\": \"Mr. Smith is my new colleague at the office. He works in the marketing department. I introduce myself to him on his first day. His position is Senior Marketing Manager. He is responsible for all advertising campaigns. Mr. Smith has a good reputation in the company. His expertise in digital marketing helps our team a lot. He is in charge of the new project. I look forward to working with him. We exchange cards during the meeting.\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为初级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}, {\"quiz_type\": \"reading\", \"passage\": \"I work in a large company. My colleague Tom and I introduce new employees to our team. Tom holds a senior position in the marketing department. He is responsible for managing the company\'s online reputation. I am in charge of product development. Many people respect Tom for his expertise in digital marketing. We always look forward to working on new projects together. When we meet business partners, we exchange cards to build professional relationships.\", \"question_text\": \"What is Tom responsible for?\", \"options\": {\"A\": \"Product development\", \"B\": \"Managing the company\'s online reputation\", \"C\": \"Introducing new employees\", \"D\": \"Exchanging cards with business partners\"}, \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为初级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}]', '[\"ppp\", \"ooo\", \"B\", \"B\"]', '[null, null, null, null]', '[{\"question_index\": 0, \"user_answer\": \"ppp\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"无法评估翻译质量，因为缺少英文原文和有效的翻译内容。学生只提供了\'ppp\'，这不是一个有效的翻译尝试。\\n\\n💡 改进建议：\\n• 请提供完整的英文原文和认真的翻译尝试\", \"explanation\": \"\"}, {\"question_index\": 1, \"user_answer\": \"ooo\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.2, \"feedback\": \"字数严重不足（1词），无法进行详细评分。建议至少150词。\", \"explanation\": \"\"}, {\"question_index\": 2, \"user_answer\": \"B\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"标准答案为None，而学生选择了B，两者不匹配。\", \"explanation\": \"\"}, {\"question_index\": 3, \"user_answer\": \"B\", \"correct_answer\": null, \"is_correct\": false, \"score\": 0.0, \"feedback\": \"标准答案为None，表示该题没有正确答案或所有选项均不正确。学生选择了B，与标准答案不符。\", \"explanation\": \"\"}]', 5, 0, 17, NULL, 1, NULL, '2026-01-31 06:29:16', '2026-01-31 06:28:39', 66);
