INSERT INTO `quiz_records` VALUES (114, 2, 36, NULL, 'random', 'mixed', '中级', 1, '[{\"quiz_type\": \"translation\", \"question_text\": \"我介绍一位新同事。她负责我们部门的市场职位。她拥有很好的专业知识和声誉，并且期待与大家交换名片。\", \"correct_answer\": \"I introduce a new colleague. She is in charge of the marketing position in our department. She has great expertise and a good reputation, and she looks forward to exchanging cards with everyone.\", \"explanation\": \"本题考察一般现在时态的运用，以及单词 \'colleague\' (同事), \'introduce\' (介绍), \'position\' (职位), \'department\' (部门), \'expertise\' (专业知识), \'reputation\' (声誉) 和短语 \'in charge of\' (负责), \'look forward to\' (期待), \'exchange cards\' (交换名片) 的翻译。句子结构为并列句，需要注意动词 \'introduce\', \'is\', \'has\', \'looks forward to\' 的时态和主谓一致。\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}]', NULL, NULL, NULL, 0, 0, 0, NULL, 0, NULL, NULL, '2026-02-22 14:52:11', 66);
