INSERT INTO `subsections` VALUES (202, 84, '1.1.1 掌握核心商务会面词汇', '能够准确拼写并使用商务会面场景下的高频词汇。', '【知识点内容】\n[知识点:单词]\ncolleague (n. 同事)\nintroduce (v. 介绍)\nposition (n. 职位)\ndepartment (n. 部门)\nresponsible (adj. 负责的)\nreputation (n. 声誉)\nexpertise (n. 专业知识)\nin charge of (负责)\nlook forward to (期待)\nexchange cards (交换名片)\n', NULL, 20, 85, 15, 1, '2026-02-22 07:05:58', '2026-02-22 07:05:58', NULL);
INSERT INTO `subsections` VALUES (203, 84, '1.1.2 掌握自我介绍语法', '熟练使用一般现在时进行自我介绍和描述工作职责，区分不同人称的动词变化。', '【知识点内容】\n[知识点:语法]\n核心语法：一般现在时\n主要用于表示习惯性、规律性或普遍性的动作\n{结构:主语 + 基本动词\n用法： I/you + 动词原形}\n{结构:主语 + 基本动词\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\n', NULL, 20, 80, 10, 2, '2026-02-22 07:05:58', '2026-02-22 07:05:58', NULL);
INSERT INTO `subsections` VALUES (204, 85, '1.2.1 电话沟通核心词汇与短语', '掌握电话预约、留言及确认行程相关的词汇和短语。', '【知识点内容】\n[知识点:单词]\nappointment (n. 预约/约会)\nschedule (v. 安排; n. 时间表)\navailable (adj. 有空的)\nconfirm (v. 确认)\npostpone (v. 推迟)\nurgent (adj. 紧急的)\nleave a message (留言)\ncall back (回电)\nput through (转接)\nhold on (稍等)\n', NULL, 25, 85, 15, 1, '2026-02-22 07:05:58', '2026-02-22 07:05:59', NULL);
INSERT INTO `subsections` VALUES (205, 85, '1.2.2 委婉表达与情态动词', '使用情态动词 (Could, Would, May) 进行礼貌的请求和询问。', '【知识点内容】\n[知识点:语法]\n核心语法：礼貌情态动词\n{用法：请求对方做某事（提出要求）\n结构：Could / Would + you + 动词原形 + ...?}\n{用法：请求允许自己做某事（征得许可）\n结构：May / Could + I + 动词原形 + ...?}\n', NULL, 25, 80, 10, 2, '2026-02-22 07:05:59', '2026-02-22 07:05:59', NULL);
INSERT INTO `subsections` VALUES (206, 86, '1.3.1 电话沟通核心词汇与短语', '掌握电话预约、留言及确认行程相关的词汇和短语。', '【知识点内容】\n[知识点:单词]\nappointment (n. 预约/约会)\nschedule (v. 安排; n. 时间表)\navailable (adj. 有空的)\nconfirm (v. 确认)\npostpone (v. 推迟)\nurgent (adj. 紧急的)\nleave a message (留言)\ncall back (回电)\nput through (转接)\nhold on (稍等)\n', NULL, 25, 85, 15, 1, '2026-02-22 07:05:59', '2026-02-22 07:05:59', NULL);
INSERT INTO `subsections` VALUES (207, 86, '1.3.2 委婉表达与情态动词', '使用情态动词 (Could, Would, May) 进行礼貌的请求和询问。', '【知识点内容】\n[知识点:语法]\n核心语法：礼貌情态动词\n{用法：请求对方做某事（提出要求）\n结构：Could / Would + you + 动词原形 + ...?}\n{用法：请求允许自己做某事（征得许可）\n结构：May / Could + I + 动词原形 + ...?}\n', NULL, 25, 80, 10, 2, '2026-02-22 07:05:59', '2026-02-22 07:05:59', NULL);
