INSERT INTO `wrong_questions` VALUES (107, 2, 90, 36, 167, 'grammar', '{\"question_text\": \"选择正确的选项来完成句子：\\nMy mother ______ breakfast for our family every morning.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"cook\", \"B\": \"cooks\", \"C\": \"cooked\", \"D\": \"cooking\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\"}}', '\"A\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 06:34:33', '2026-01-30 15:20:07', 66);
INSERT INTO `wrong_questions` VALUES (108, 2, 90, 36, 167, 'grammar', '{\"question_text\": \"选择正确的选项来完成句子：\\nMy sister ______ her homework every evening.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"do\", \"B\": \"does\", \"C\": \"did\", \"D\": \"doing\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\"}}', '\"A\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 06:34:33', '2026-01-30 15:20:07', 66);
