INSERT INTO `wrong_questions` VALUES (112, 2, 91, 36, 167, 'grammar', '{\"question_text\": \"选择正确的选项来完成句子：\\nMy mother ______ delicious meals every weekend.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"cook\", \"B\": \"cooks\", \"C\": \"cooked\", \"D\": \"cooking\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\"}}', '\"A\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 06:35:33', '2026-01-30 15:20:07', 66);
INSERT INTO `wrong_questions` VALUES (113, 2, 92, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"职位\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"position\", \"explanation\": \"\", \"meta\": {\"word\": \"position (n. 职位)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词position (n. 职位)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"qwe\"', '\"position\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:05:20', '2026-01-30 15:20:07', 66);
INSERT INTO `wrong_questions` VALUES (114, 2, 92, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"一个组织中负责特定职能的单位\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"department\", \"explanation\": \"\", \"meta\": {\"word\": \"department (n. 部门)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词department (n. 部门)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"qwe\"', '\"department\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:05:20', '2026-01-30 15:20:07', 66);
INSERT INTO `wrong_questions` VALUES (115, 2, 93, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一名新员工，第一天上班时需要向团队成员做自我介绍。写一篇短文介绍你自己，包括你的职位、所在部门以及你的工作职责。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下词汇：colleague, introduce, position, department, responsible\", \"必须体现一般现在时的用法\"], \"word_count\": \"80-120词\"}', '\"ppppp\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 14:13:43', '2026-01-30 14:13:43', NULL);
INSERT INTO `wrong_questions` VALUES (116, 2, 93, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"她负责市场部门的声誉管理。\", \"correct_answer\": \"\", \"explanation\": \"\"}', '\"iiiiiiiiii\"', '\"\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:13:43', '2026-01-30 14:13:43', NULL);
INSERT INTO `wrong_questions` VALUES (117, 2, 93, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一名公司员工，你需要向新同事介绍你自己和你的工作。请写一段简短的自我介绍，描述你的职位、部门以及你负责的工作。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下词汇中的至少5个：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须使用一般现在时来描述你当前的工作情况和职责\"], \"word_count\": \"80-120词\"}', '\"iiiiiiiiiiiiii\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 14:13:43', '2026-01-30 14:13:43', NULL);
INSERT INTO `wrong_questions` VALUES (118, 2, 93, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下句子翻译成英文：他在部门负责项目，并期待与同事交换名片。\"}', '\"iiiiiiiiiiiiiii\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:13:43', '2026-01-30 14:13:43', NULL);
INSERT INTO `wrong_questions` VALUES (119, 2, 94, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"我的同事李先生负责销售部门，他经常向新客户介绍我们的公司声誉和专业知识，并期待与他们交换名片。\"}', '\"wwwwwwwww\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:15:42', '2026-01-30 14:15:42', NULL);
INSERT INTO `wrong_questions` VALUES (120, 2, 94, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"Imagine you are a new employee in a company. Write a short self-introduction to your colleagues. In your writing, you should introduce yourself and your position, describe your department and what you are responsible for, and express what you look forward to in your new job.\", \"requirements\": [\"Word count: 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use the simple present tense correctly\"], \"word_count\": \"80-120\"}', '\"wwwwwwwwwww\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 14:15:42', '2026-01-30 14:15:42', NULL);
INSERT INTO `wrong_questions` VALUES (121, 2, 94, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一名在公司工作的员工。请写一段短文，描述你的工作职责以及你如何与同事互动。内容包括你的职位、所在部门、你负责的工作，以及你与新同事交流的方式。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下词汇：colleague, introduce, position, department, responsible, in charge of, look forward to\", \"使用一般现在时描述你的日常工作职责和与同事的互动\"], \"word_count\": \"80-120词\"}', '\"wwwwwwwww\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 14:15:42', '2026-01-30 14:15:42', NULL);
INSERT INTO `wrong_questions` VALUES (122, 2, 94, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文翻译成英文：我的同事李明负责销售部门，他期待与新客户交换名片并介绍我们公司的专业知识和声誉。\"}', '\"wwwwwww\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:15:42', '2026-01-30 14:15:42', NULL);
INSERT INTO `wrong_questions` VALUES (123, 2, 94, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"我的同事李明负责市场部门，他期待与新客户交换名片并介绍我们的专业知识和声誉。\", \"correct_answer\": \"\", \"explanation\": \"\"}', '\"ppp\"', '\"\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:15:42', '2026-01-30 14:15:42', NULL);
INSERT INTO `wrong_questions` VALUES (124, 2, 96, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：李经理是我们的同事，他负责销售部门，以其专业知识享有良好声誉，并期待在会议上与客户交换名片。\"}', '\"oo\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:28:44', '2026-01-30 14:28:44', NULL);
INSERT INTO `wrong_questions` VALUES (125, 2, 96, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一家公司的新员工，你需要向团队成员介绍自己和你的一位同事。请写一篇短文介绍你们各自的职位、部门、工作职责以及你对未来合作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个给定词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须正确使用一般现在时，包括第三人称单数的变化\"], \"word_count\": \"80-120词\"}', '\"pp\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 14:28:44', '2026-01-30 14:28:44', NULL);
INSERT INTO `wrong_questions` VALUES (126, 2, 96, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"question_text\": \"What does the word \'responsible\' mean in the passage?\", \"options\": {\"A\": \"擅长的\", \"B\": \"负责的\", \"C\": \"专业的\", \"D\": \"有经验的\"}, \"passage\": \"Tom is my new colleague at the office. He works in the Marketing department. I introduce him to everyone on his first day. Tom is responsible for social media campaigns. He is in charge of the company\'s online presence. We exchange cards during the morning meeting. Tom has excellent expertise in digital marketing. He builds a good reputation quickly in the company. Everyone looks forward to working with him on future projects.\"}', '\"D\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:28:44', '2026-01-30 14:28:44', NULL);
INSERT INTO `wrong_questions` VALUES (127, 2, 96, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事经常向新员工介绍他的职位和部门，他负责维护公司的声誉并展示他的专业知识，他期待与客户交换名片。\"}', '\"ppp\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 14:28:44', '2026-01-30 14:28:44', NULL);
INSERT INTO `wrong_questions` VALUES (128, 2, 96, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"Write a self-introduction email to your new colleagues on your first day at a new company.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the given vocabulary words (colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards)\", \"Use the simple present tense correctly to describe your job responsibilities and expectations\", \"Include information about your position, department, and what you are responsible for\", \"Mention how you look forward to working with your new colleagues\"], \"word_count\": \"80-120 words\"}', '\"ppp\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 14:28:44', '2026-01-30 14:28:44', NULL);
INSERT INTO `wrong_questions` VALUES (129, 2, 97, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文翻译成英文：\", \"passage\": \"我的同事李明负责市场部，他经常向新员工介绍自己的职位和部门，并期待与客户交换名片以建立良好的声誉。\"}', '\"lll\"', 'null', 0.1, NULL, 0, 0, NULL, NULL, '2026-01-30 15:27:10', '2026-01-30 15:27:10', 66);
INSERT INTO `wrong_questions` VALUES (130, 2, 97, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"passage\": \"Tom works in the Marketing Department. He is responsible for the company\'s online campaigns. His colleague, Lisa, introduces him to new team members. Lisa has a good reputation in the company because of her expertise in social media. Tom is in charge of the email marketing team. They look forward to launching the new product next month. At business meetings, they always exchange cards with potential clients.\", \"question_text\": \"According to the passage, what is Tom responsible for?\", \"options\": {\"A\": \"Introducing new team members\", \"B\": \"The company\'s online campaigns\", \"C\": \"Exchanging cards with clients\", \"D\": \"Managing Lisa\'s work\"}}', '\"C\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 15:27:10', '2026-01-30 15:27:10', 66);
INSERT INTO `wrong_questions` VALUES (131, 2, 97, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：作为市场部的负责人，我经常向新同事介绍我的职位和专业知识，并与他们交换名片，我期待与他们合作以维护我们部门的声誉。\", \"correct_answer\": \"\", \"explanation\": \"\"}', '\"ooo\"', '\"\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 15:27:10', '2026-01-30 15:27:10', 66);
INSERT INTO `wrong_questions` VALUES (132, 2, 97, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"question_text\": \"What does \'responsible\' mean in the context of the passage?\", \"options\": {\"A\": \"Answerable for duties\", \"B\": \"Able to respond quickly\", \"C\": \"Having a lot of work\", \"D\": \"Being important\"}, \"passage\": \"John works in a large company. He has many colleagues in his department. His position is Marketing Manager. He is responsible for promoting products. John has a good reputation in the company because of his expertise. He is in charge of the marketing team. Every day, John introduces new ideas to his team. They look forward to the weekly meetings. When they meet clients, they always exchange cards. John enjoys his job and works hard every day.\"}', '\"D\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 15:27:10', '2026-01-30 15:27:10', 66);
INSERT INTO `wrong_questions` VALUES (133, 2, 97, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"Write a short paragraph introducing a new colleague to your team members. Include information about his/her position, department, responsibilities, and professional background.\", \"requirements\": [\"Write between 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use the simple present tense correctly to describe the colleague\'s responsibilities and role\"], \"word_count\": \"80-120 words\"}', '\"00\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 15:27:10', '2026-01-30 15:27:10', 66);
INSERT INTO `wrong_questions` VALUES (134, 2, 98, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你刚加入一家新公司，需要在部门会议上做自我介绍。请写一段80-120词的短文，介绍你的职位、职责以及你对新工作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用以下至少5个词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须使用一般现在时描述你的职责和日常工作\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"dsa\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 16:06:22', '2026-01-30 16:06:22', 66);
INSERT INTO `wrong_questions` VALUES (135, 2, 98, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事李明经常向新员工介绍他的职位和部门，他负责维护公司的声誉，并期待与客户交换名片以展示他的专业知识。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"asd\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 16:06:22', '2026-01-30 16:06:22', 66);
