INSERT INTO `wrong_questions` VALUES (139, 2, 99, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"question_text\": \"According to the passage, what is the department known for?\", \"options\": {\"A\": \"Having many colleagues\", \"B\": \"Good reputation for creativity\", \"C\": \"Digital marketing expertise\", \"D\": \"Exchanging cards\"}, \"passage\": \"In our company, I work with many colleagues in the marketing department. My manager introduces new team members to everyone. She holds a senior position and is responsible for important projects. Our department has a good reputation for creativity. John, who is in charge of digital marketing, has great expertise in social media. We always exchange cards during business meetings. I look forward to working with this talented team every day.\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为中级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"B\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 16:31:36', '2026-01-30 16:31:36', 66);
INSERT INTO `wrong_questions` VALUES (140, 2, 99, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事负责介绍新员工的职位和部门，他期待与每个人交换名片。\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"ppp\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 16:31:36', '2026-01-30 16:31:36', 66);
INSERT INTO `wrong_questions` VALUES (141, 2, 99, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"Write a short paragraph to introduce a new colleague to your team members. Include information about their position, department, and what they are responsible for. Also mention how your team will benefit from their expertise and reputation.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use simple present tense correctly, including third person singular forms (e.g., \'He works\' not \'He work\')\"], \"word_count\": \"80-120 words\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"pp\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 16:31:36', '2026-01-30 16:31:36', 66);
INSERT INTO `wrong_questions` VALUES (142, 2, 99, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一家公司的新员工，你需要在部门会议上做一个简短的自我介绍。请写一篇80-120词的短文，介绍你的职位、工作职责以及你对新工作的期待。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个下列词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须使用一般现在时描述你的工作职责和习惯\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange ...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"pp\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 16:31:36', '2026-01-30 16:31:36', 66);
