INSERT INTO `wrong_questions` VALUES (146, 2, 100, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"假设你是一家公司的新员工，请写一篇短文介绍你的工作情况。在短文中，你需要描述你的职位、所在部门、你的工作职责以及你与同事的合作关系。\", \"requirements\": [\"字数范围：80-120词\", \"必须使用至少5个以下词汇：colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"必须正确使用一般现在时\"], \"word_count\": \"80-120词\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为中级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"qqq\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-30 16:52:46', '2026-01-30 16:52:46', 66);
INSERT INTO `wrong_questions` VALUES (147, 2, 100, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"question_text\": \"What does the word \'reputation\' mean in the passage?\", \"options\": {\"A\": \"The ability to do something well\", \"B\": \"The opinions that people have about someone or something\", \"C\": \"The department where someone works\", \"D\": \"The position that someone holds in a company\"}, \"passage\": \"John is my colleague at the marketing department. He introduces new products to clients. His position is Senior Manager. John is responsible for the Asia region. He has a good reputation for his expertise in digital marketing. He is in charge of a team of ten people. We look forward to working together on the new project. We often exchange cards at business meetings.\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为中级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"B\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 16:52:46', '2026-01-30 16:52:46', 66);
INSERT INTO `wrong_questions` VALUES (148, 2, 100, 36, NULL, 'mixed', '{\"quiz_type\": \"translation\", \"question_text\": \"请将以下中文句子翻译成英文：我的同事经常向新员工介绍我们的职位、部门以及我们负责的内容，我们期待与客户交换名片并展示公司的声誉和专业知识。\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成中译英翻译题目。题目需严格围绕给定词汇和核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，出题的难度为中级的难度，难度需体现为句子的词汇复杂度（如初级用基础词汇，高级可结合短语搭配）和语法结构复杂性（如初级为简单句，高级可含并列成分），出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容：\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"qqq\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-30 16:52:46', '2026-01-30 16:52:46', 66);
INSERT INTO `wrong_questions` VALUES (149, 1, 103, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"介绍\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"introduce\", \"explanation\": \"\", \"meta\": {\"word\": \"introduce (v. 介绍)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词introduce (v. 介绍)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ppp\"', '\"introduce\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:26:35', '2026-01-31 06:26:35', NULL);
INSERT INTO `wrong_questions` VALUES (150, 1, 103, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"部门\\\" 请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"department\", \"explanation\": \"\", \"meta\": {\"word\": \"department (n. 部门)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词department (n. 部门)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"oo\"', '\"department\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:26:35', '2026-01-31 06:26:35', NULL);
INSERT INTO `wrong_questions` VALUES (151, 10, 102, 36, 166, 'word_training', '{\"question_text\": \"请选择\\\"expertise\\\"这个单词正确的中文意思：\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"专门技能\", \"B\": \"经验\", \"C\": \"专业知识\", \"D\": \"期望\"}, \"correct_answer\": \"C\", \"explanation\": \"\", \"meta\": {\"word\": \"expertise (n. 专业知识)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n选择题：给出英文单词expertise (n. 专业知识)，要求从四个中文选项A、B、C、D中选择正确的中文意思,选择题的干扰项需设计得合理，需包含语义相近或词形相近的错误选项，只出题即可，不要说明\\n输出形式——以单词abandon n.抛弃 为例：\\n请选择\\\"abandon\\\"这个单词正确的中文意思：\\nA. 抛弃\\nB. 遗失\\nC. 给与\\nD. 贡献\"}}', '\"A\"', '\"C\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:26:36', '2026-01-31 06:26:36', NULL);
INSERT INTO `wrong_questions` VALUES (152, 10, 102, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"_________\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"in charge of\", \"explanation\": \"\", \"meta\": {\"word\": \"in charge of (负责)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词in charge of (负责)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ppp\"', '\"in charge of\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:26:36', '2026-01-31 06:26:36', NULL);
INSERT INTO `wrong_questions` VALUES (153, 10, 102, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"介绍\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"introduce\", \"explanation\": \"\", \"meta\": {\"word\": \"introduce (v. 介绍)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词introduce (v. 介绍)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ppp\"', '\"introduce\"', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:26:36', '2026-01-31 06:26:36', NULL);
