INSERT INTO `wrong_questions` VALUES (155, 10, 104, 36, NULL, 'mixed', '{\"quiz_type\": \"writing\", \"question_text\": \"Write a short self-introduction for a new job. Imagine you are the new employee at a company and you need to introduce yourself to your colleagues.\", \"requirements\": [\"Write 80-120 words\", \"Use at least 5 of the following words: colleague, introduce, position, department, responsible, reputation, expertise, in charge of, look forward to, exchange cards\", \"Use simple present tense to describe your job responsibilities and daily activities\"], \"word_count\": \"80-120 words\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语写作题目。题目需以给定词汇及核心语法进行设计，给定词汇只考察给定的那个中文意思，其他的中文意思不考，要求考生在写作中运用这些词汇和语法，出题的难度为初级的难度，写作要求需包含：字数范围（例如：80-120词）、必须使用的至少5个给定词汇和必须体现核心语法的语法点，难度需通过写作场景的具体性（初级为直接描述，高级需加入逻辑延伸）、词汇运用深度（初级为单词汇，高级需搭配短语）和句子结构多样性（初级为简单句，高级可含复合句）体现，出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容)\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"ooo\"', 'null', 0.2, NULL, 0, 0, NULL, NULL, '2026-01-31 06:29:16', '2026-01-31 06:29:16', 66);
INSERT INTO `wrong_questions` VALUES (156, 10, 104, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"question_text\": \"What is Mr. Smith\'s position in the company?\", \"options\": {\"A\": \"Marketing Department Manager\", \"B\": \"Senior Marketing Manager\", \"C\": \"Digital Marketing Expert\", \"D\": \"Advertising Campaign Manager\"}, \"passage\": \"Mr. Smith is my new colleague at the office. He works in the marketing department. I introduce myself to him on his first day. His position is Senior Marketing Manager. He is responsible for all advertising campaigns. Mr. Smith has a good reputation in the company. His expertise in digital marketing helps our team a lot. He is in charge of the new project. I look forward to working with him. We exchange cards during the meeting.\", \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为初级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"B\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:29:16', '2026-01-31 06:29:16', 66);
INSERT INTO `wrong_questions` VALUES (157, 10, 104, 36, NULL, 'mixed', '{\"quiz_type\": \"reading\", \"passage\": \"I work in a large company. My colleague Tom and I introduce new employees to our team. Tom holds a senior position in the marketing department. He is responsible for managing the company\'s online reputation. I am in charge of product development. Many people respect Tom for his expertise in digital marketing. We always look forward to working on new projects together. When we meet business partners, we exchange cards to build professional relationships.\", \"question_text\": \"What is Tom responsible for?\", \"options\": {\"A\": \"Product development\", \"B\": \"Managing the company\'s online reputation\", \"C\": \"Introducing new employees\", \"D\": \"Exchanging cards with business partners\"}, \"meta\": {\"word\": \"[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换...\", \"prompt\": \"请根据以下提供的知识内容，生成英语阅读理解题。题目需包含一篇短文（基于给定词汇和语法编写）及配套问题。短文需围绕“职场同事、部门职责或工作场景”展开，重点融入给定词汇和核心语法，给定词汇只考察给定的那个中文意思，其他的中文意思不考，短文长度：80-120词，内容清晰连贯，逻辑简单，至少使用6个给定词汇，核心语法的句子占比不低于60%。请针对短文设计1个单项选择题，必须包含题干和4个选项（A、B、C、D）。题目可以是词汇理解题（如文中划线词含义）、细节信息题或语法判断题。难度为初级的难度，难度需通过短文词汇复杂度、句子结构和问题深度体现。出1道题目，只需要和答题相关的内容，其他和答题无关的内容不要且不需要答案，下面是知识内容\\n\\n下面是知识内容：\\n[知识点:单词]\\ncolleague (n. 同事)\\nintroduce (v. 介绍)\\nposition (n. 职位)\\ndepartment (n. 部门)\\nresponsible (adj. 负责的)\\nreputation (n. 声誉)\\nexpertise (n. 专业知识)\\nin charge of (负责)\\nlook forward to (期待)\\nexchange cards (交换名片)\\n\\n[知识点:语法]\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n{结构:主语 + 基本动词\\n用法： I/you + 动词原形}\\n{结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es}\\n\\n\"}}', '\"B\"', 'null', 0, NULL, 0, 0, NULL, NULL, '2026-01-31 06:29:16', '2026-01-31 06:29:16', 66);
INSERT INTO `wrong_questions` VALUES (158, 10, 105, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"管理某事或某人的职责\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"in charge of\", \"explanation\": \"\", \"meta\": {\"word\": \"in charge of (负责)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词in charge of (负责)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ppp\"', '\"in charge of\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:14:00', '2026-02-02 16:14:00', NULL);
INSERT INTO `wrong_questions` VALUES (159, 10, 105, 36, 166, 'word_training', '{\"question_text\": \"单词默写，指在一个组织或公司中所担任的工作职务或角色。请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"position\", \"explanation\": \"\", \"meta\": {\"word\": \"position (n. 职位)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词position (n. 职位)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ppppp\"', '\"position\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:14:00', '2026-02-02 16:14:00', NULL);
INSERT INTO `wrong_questions` VALUES (160, 10, 106, 36, 166, 'word_training', '{\"question_text\": \"请选择\\\"in charge of\\\"这个短语正确的中文意思：\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"负责\", \"B\": \"管理\", \"C\": \"照顾\", \"D\": \"控制\"}, \"correct_answer\": \"A\", \"explanation\": \"\", \"meta\": {\"word\": \"in charge of (负责)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n选择题：给出英文单词in charge of (负责)，要求从四个中文选项A、B、C、D中选择正确的中文意思,选择题的干扰项需设计得合理，需包含语义相近或词形相近的错误选项，只出题即可，不要说明\\n输出形式——以单词abandon n.抛弃 为例：\\n请选择\\\"abandon\\\"这个单词正确的中文意思：\\nA. 抛弃\\nB. 遗失\\nC. 给与\\nD. 贡献\"}}', '\"B\"', '\"A\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:22:16', '2026-02-02 16:22:16', NULL);
INSERT INTO `wrong_questions` VALUES (161, 10, 106, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"声誉\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"reputation\", \"explanation\": \"\", \"meta\": {\"word\": \"reputation (n. 声誉)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词reputation (n. 声誉)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"pppp\"', '\"reputation\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:22:16', '2026-02-02 16:22:16', NULL);
INSERT INTO `wrong_questions` VALUES (162, 10, 106, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"负责的\\\"\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"responsible\", \"explanation\": \"\", \"meta\": {\"word\": \"responsible (adj. 负责的)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词responsible (adj. 负责的)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"oooo\"', '\"responsible\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:22:16', '2026-02-02 16:22:16', NULL);
INSERT INTO `wrong_questions` VALUES (163, 10, 106, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：\\\"部门\\\" 请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"department\", \"explanation\": \"\", \"meta\": {\"word\": \"department (n. 部门)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词department (n. 部门)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ooo\"', '\"department\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:22:16', '2026-02-02 16:22:16', NULL);
INSERT INTO `wrong_questions` VALUES (164, 10, 106, 36, 166, 'word_training', '{\"question_text\": \"单词默写，在商务场合中，人们初次见面时通常会进行一种社交礼仪，即互相分享个人的联系信息，这一行为的英文表达是：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"exchange cards\", \"explanation\": \"\", \"meta\": {\"word\": \"exchange cards (交换名片)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词exchange cards (交换名片)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"123\"', '\"exchange cards\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:22:16', '2026-02-02 16:22:16', NULL);
INSERT INTO `wrong_questions` VALUES (165, 10, 108, 36, 167, 'grammar', '{\"question_text\": \"选择正确的选项来完成句子：They ______ basketball every weekend.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"play\", \"B\": \"plays\", \"C\": \"played\", \"D\": \"playing\"}, \"correct_answer\": \"A\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\"}}', '\"B\"', '\"A\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:34:44', '2026-02-02 16:34:44', NULL);
INSERT INTO `wrong_questions` VALUES (166, 10, 108, 36, 167, 'grammar', '{\"question_text\": \"选择正确的选项来完成句子：My mother ______ delicious meals every weekend.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"cook\", \"B\": \"cooks\", \"C\": \"cooked\", \"D\": \"cooking\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\"}}', '\"A\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:34:44', '2026-02-02 16:34:44', NULL);
INSERT INTO `wrong_questions` VALUES (167, 10, 108, 36, 167, 'grammar', '{\"question_text\": \"My parents ______ dinner at 7 PM every day.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"cook\", \"B\": \"cooks\", \"C\": \"cooked\", \"D\": \"cooking\"}, \"correct_answer\": \"A\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\"}}', '\"B\"', '\"A\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-02 16:34:44', '2026-02-02 16:34:44', NULL);
INSERT INTO `wrong_questions` VALUES (168, 2, 109, 36, 166, 'word_training', '{\"question_text\": \"单词默写，中文意思：“职位”\\n请默写英文单词：______\", \"quiz_type\": \"blank\", \"options\": [], \"correct_answer\": \"position\", \"explanation\": \"\", \"meta\": {\"word\": \"position (n. 职位)\", \"prompt\": \"你是一名专业的英语出题专家，现在请你根据下面的要求进行出1道题\\n默写题: 给出单词position (n. 职位)的中文意思，要求默写出对应的英文单词\\n输出形式：以单词abandon n.抛弃 为例：\\n单词默写，中文意思：\\\"抛弃\\\"\\n请默写英文单词：______\"}}', '\"ll\"', '\"position\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-22 08:33:16', '2026-02-22 08:33:16', NULL);
