INSERT INTO `wrong_questions` VALUES (187, 2, 113, 36, 167, 'grammar', '{\"question_text\": \"My neighbor usually ______ his dog for a walk in the park every morning.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"take\", \"B\": \"takes\", \"C\": \"took\", \"D\": \"taking\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\"}}', '\"C\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-22 14:48:23', '2026-02-22 14:48:23', NULL);
INSERT INTO `wrong_questions` VALUES (188, 2, 113, 36, 167, 'grammar', '{\"question_text\": \"My sister usually ______ her favorite book before bedtime.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"read\", \"B\": \"reads\", \"C\": \"reading\", \"D\": \"readed\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法：第三人称单数（如 he, she, it）使用动词加-s 或 -es\"}}', '\"C\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-22 14:48:23', '2026-02-22 14:48:23', NULL);
INSERT INTO `wrong_questions` VALUES (189, 2, 113, 36, 167, 'grammar', '{\"question_text\": \"Every morning, I ______ a glass of water before breakfast.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"drink\", \"B\": \"drinks\", \"C\": \"drank\", \"D\": \"drinking\"}, \"correct_answer\": \"A\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\"}}', '\"C\"', '\"A\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-22 14:48:23', '2026-02-22 14:48:23', NULL);
INSERT INTO `wrong_questions` VALUES (190, 2, 113, 36, 167, 'grammar', '{\"question_text\": \"My sister ______ her teeth twice a day.\", \"quiz_type\": \"choice\", \"options\": {\"A\": \"brush\", \"B\": \"brushes\", \"C\": \"brushed\", \"D\": \"brushing\"}, \"correct_answer\": \"B\", \"explanation\": \"\", \"meta\": {\"word\": \"核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\", \"prompt\": \"你是一位经验丰富的英语教研员，专门负责英语语法题目的设计，现在请你根据以下的要求进行出1道题:\\n题目为选择题，题目内容应结合实际或者生活，只生成题即可，不要写多余的东西，出题形式例如：\\n选择正确的选项来完成句子：\\nHe ______ to school every day.\\nA. go\\nB. goes\\nC. went\\nD. going\\n参考上面的出题形式进行出题，下面是考察的语法内容\\n核心语法：一般现在时\\n主要用于表示习惯性、规律性或普遍性的动作\\n结构:主语 + 基本动词\\n用法： I/you + 动词原形\"}}', '\"B\"', '\"B\"', 0, NULL, 0, 0, NULL, NULL, '2026-02-22 14:48:23', '2026-02-22 14:48:23', NULL);
